// THE CONTRACT. Do not edit this file when you fork the page: redesign BotPage.jsx instead.
//
// Whatever your interface looks like, it must end by handing submitBot() one object shaped like CHOICES below.
// submitBot() turns it into the record the Ensemble's Airtable table expects (the same shape the server checks in
// lib/custom-chatbot/schema.ts) and POSTs it to /api/submit. watch.mjs and Watcher.jsx check that you still do.

// What the student chooses. Every key is required except `extras`.
export const CHOICES = {
  botName: "Your bot's name (1–80 characters). The same name again updates your bot.",
  studentName: "Your name (1–120 characters).",
  prompt: "Which instructions: one of the catalog's prompts (ghazal, haiku, sonnet).",
  pack: "Which knowledge pack: phaedrus, frankenstein, analects, or none.",
  material: "How much of the pack: voice, assigned, more, or whole.",
  delivery: "How the pack reaches the model: full, lexical, semantic, or agentic.",
  extras: "Optional. Anything else your interface collects (colors, a costume, a mood, notes), as text or JSON. Saved as long text.",
};
export const REQUIRED = ["botName", "studentName", "prompt", "pack", "material", "delivery"];
export const PACKS = ["phaedrus", "frankenstein", "analects", "none"];
export const MATERIALS = ["voice", "assigned", "more", "whole"];
export const DELIVERIES = ["full", "lexical", "semantic", "agentic"];

// Problems with a set of choices, as { key: message }. Empty object = ready to submit.
export function check(choices, catalog) {
  const problems = {};
  const c = choices && typeof choices === "object" ? choices : {};
  for (const key of Object.keys(c)) if (!(key in CHOICES)) problems[key] = `"${key}" is not part of the contract. Put extra data in extras instead.`;
  const text = (key, max) => {
    const value = c[key];
    if (typeof value !== "string" || !value.trim()) problems[key] = `${key} is missing.`;
    else if (value.trim().length > max) problems[key] = `${key} is longer than ${max} characters.`;
  };
  text("botName", 80);
  text("studentName", 120);
  const prompts = Object.keys(catalog?.prompts ?? {});
  if (!prompts.includes(c.prompt)) problems.prompt = `prompt must be one of: ${prompts.join(", ") || "(catalog not loaded)"}.`;
  if (!PACKS.includes(c.pack)) problems.pack = `pack must be one of: ${PACKS.join(", ")}.`;
  if (!MATERIALS.includes(c.material)) problems.material = `material must be one of: ${MATERIALS.join(", ")}.`;
  if (!DELIVERIES.includes(c.delivery)) problems.delivery = `delivery must be one of: ${DELIVERIES.join(", ")}.`;
  if (c.extras !== undefined && typeof c.extras !== "string") problems.extras = "extras must be text (use JSON.stringify for objects).";
  return problems;
}

// The choices -> the record /api/submit accepts. catalog = { prompts: { id: text }, voices: { pack: text } },
// which page.jsx loads on the server and passes to BotPage.
export function toSubmission(choices, catalog) {
  return {
    agentName: (choices.botName ?? "").trim(),
    student: (choices.studentName ?? "").trim(),
    iconUrl: "",
    framingPrompt: catalog?.prompts?.[choices.prompt] ?? "",
    knowledge: catalog?.voices?.[choices.pack] ?? "",
    notes: "",
    model: "",
    settings: { genre: choices.prompt, pack: choices.pack, material: choices.material, delivery: choices.delivery },
    extras: typeof choices.extras === "string" ? choices.extras : "",
  };
}

// Send it. Returns { ok, ... } from the server; with { dry: true } it is only checked, never saved.
export async function submitBot(choices, catalog, { dry = false } = {}) {
  const problems = check(choices, catalog);
  if (Object.keys(problems).length) return { ok: false, error: "Some choices are missing or wrong.", fields: problems };
  const response = await fetch(`/api/submit${dry ? "?dry=1" : ""}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(toSubmission(choices, catalog)),
  });
  return response.json().catch(() => ({ ok: false, error: `The server answered ${response.status}.` }));
}
